import{_ as o,C as t,c as i,o as s,aj as l,G as n,w as d}from"./chunks/framework.Bfdr4H5E.js";const b=JSON.parse('{"title":"Finding Your Style","description":"","frontmatter":{"outline":"deep","prev":{"text":"Market Segments Basics Explained","link":"/trading-with-pav/market-segments-basics-explained"},"next":{"text":"What Instruments (Scripts) to Trade","link":"/trading-with-pav/what-instruments-scripts-to-trade"}},"headers":[],"relativePath":"trading-with-pav/finding-your-style.md","filePath":"trading-with-pav/finding-your-style.md"}'),h={name:"trading-with-pav/finding-your-style.md"};function u(m,e,g,c,y,p){const a=t("GraphComment"),r=t("ClientOnly");return s(),i("div",null,[e[0]||(e[0]=l('<h1 id="finding-your-style" tabindex="-1">Finding Your Style <a class="header-anchor" href="#finding-your-style" aria-label="Permalink to &quot;Finding Your Style&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#finding-your-style-1">Finding Your Style</a><ul><li><a href="#intraday-trading">Intraday trading</a></li><li><a href="#swing-trading">Swing Trading</a></li><li><a href="#long-term-investments">Long-Term Investments</a></li></ul></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="finding-your-style-1" tabindex="-1">Finding Your Style <a class="header-anchor" href="#finding-your-style-1" aria-label="Permalink to &quot;Finding Your Style&quot;">​</a></h2><p>In the previous volumes where we showed you the Market analysis, Trading Strategy and Volume setups, We didn’t stick to any particular timeframe. The reason is that those setups can be applied to any timeframe because our Trading Strategy and Volume Profile is really versatile and it isn’t time dependent.</p><p>You can use it for <strong>intraday</strong> trading, <strong>swing</strong> trading or to planning your <strong>long-term investments</strong>.<br> Important thing is to find what suits you best and then master the method. If you are still finding your style, then I suggest you try it all and see what suits you most. Also you have to select according to your profession free time.</p><h3 id="intraday-trading" tabindex="-1">Intraday trading <a class="header-anchor" href="#intraday-trading" aria-label="Permalink to &quot;Intraday trading&quot;">​</a></h3><p>We suggest that you do your intraday analysis on 5-minute to 1-hour charts (I prefer 15-30 minute charts). Look for the Price Action Volume setups I showed you and identify the strongest volume-based support/resistance zones.</p><p><strong>Trading Instruments for Intraday Trades</strong></p><p>Good trading instruments for intraday trading are those that have really high liquidity and the tightest spreads. If you trade Index Option, then the best is to start with in my opinion is the BankNifty.</p><p>With a good broker (Our Recommendation <a href="https://invite.dhan.co/?invite=KJXFR31859" target="_blank" rel="noreferrer">Dhan</a>, <a href="https://open-account.fyers.in/?utm-source=Customer-Referral&amp;utm-medium=XY00224" target="_blank" rel="noreferrer">Fyers</a>, <a href="https://zerodha.com/?c=LR6790&amp;s=CONSOLE" target="_blank" rel="noreferrer">Zerodha</a>) check brokerage.<br> BankNifty also has the best reactions to volume-based S/R levels. When you feel comfortable trading the BankNifty, then you can add Nifty 50 or another major Equity Option from Indices only, Futures or Equity Stocks. For Commodities Practice and decide not much experience because I don’t have interest in those instruments.</p><h3 id="swing-trading" tabindex="-1">Swing Trading <a class="header-anchor" href="#swing-trading" aria-label="Permalink to &quot;Swing Trading&quot;">​</a></h3><p>We suggest that you plan your swing trades on 1-hour to a Daily timeframe. I prefer planning my swing trades with 120-minute (4-hour) ~ 240-minute charts (4-hour) and with Daily charts. Such timeframes are good to help you see the bigger picture.</p><p>When I plan my swing trades, I look for the volume setups #1 – #3 on those specific timeframes (4-hour or Daily). The setups are always the same, no matter if it is intraday or swing trading.</p><p><strong>Trading Instruments for Swing Trades</strong></p><p>With swing trades, your Stop-loss and Profit Target values are much bigger and because of that the trading costs are almost neglectable.<br> For that reason, it is okay to swing trade any instruments you like. You can trade forex, indexes,<br> stocks, cryptocurrencies, oil, futures, commodities or whatever you prefer.</p><h3 id="long-term-investments" tabindex="-1">Long-Term Investments <a class="header-anchor" href="#long-term-investments" aria-label="Permalink to &quot;Long-Term Investments&quot;">​</a></h3><p>Long-term investing is good for people who don’t want to sit in front of the computer all day. There is also no need to be careful about the standard daily news because they aren’t that significant to change the course of a long-term trend development. Big financial institutions operate a lot on the higher timeframes (weekly to monthly), and therefore the volume-based strategies work pretty nicely there.</p><p>My preferred timeframe for analyzing long-term investments is from weekly to monthly. Even for long-term investments, the price action volume-based trading setups are still the same. The logic behind the setups is still the same, even if you are doing your analysis on a monthly chart.</p><p><strong>Trading Instruments for Long-Term Investments</strong></p><p>Brokerages are absolutely negligible here so you can trade any instrument you want, be it forex, stocks, indexes, cryptocurrencies, futures…<br> If you trade Futures, there is one thing that you need to be careful about though. The thing is the Monthly Expiry.</p><p>That’s all for this article next will discover What instruments to trade?</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2>',22)),n(r,null,{default:d(()=>[n(a)]),_:1})])}const v=o(h,[["render",u]]);export{b as __pageData,v as default};
